import React from 'react';
import {useCurrentFrame, useVideoConfig, AbsoluteFill} from 'remotion';
import {ThreeCanvas} from '@remotion/three';
export const SUBS = {arriba: 3000, size: 1, acento: '#ffd84d'};
export const SFX = [];
export const Escena: React.FC = () => {
  const f = useCurrentFrame();
  const {width, height} = useVideoConfig();
  return <AbsoluteFill style={{background: '#113f4d'}}><ThreeCanvas width={width} height={height}><ambientLight intensity={1} /><directionalLight position={[3, 5, 5]} intensity={2} /><mesh rotation={[0.4, f * 0.04, 0]}><cylinderGeometry args={[1.4, 1.4, 0.3, 48]} /><meshStandardMaterial color="#ffc93c" /></mesh></ThreeCanvas></AbsoluteFill>;
};
